contracts/CompanyManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./GasSwapAccessControl.sol";

/**
 * @title CompanyManager
 * @dev Manages gas companies and their branches in Rwanda
 * 
 * Companies: Kigaligas, Hash Gas, Meru Gas, Jibu Gas, SP, Oryx, Tahacel
 * Branches: Physical locations across all 30 districts
 */
contract CompanyManager is GasSwapAccessControl {
    
    // Structs
    struct Company {
        uint256 id;
        string name;
        string code;           // Short code like "KIGALIGAS", "HASH"
        bool isActive;
        address adminWallet;
        uint256 createdAt;
    }
    
    struct Branch {
        uint256 id;
        uint256 companyId;
        string name;
        string district;       // Rwanda district name
        string location;       // Specific address
        bool isActive;
        uint256 createdAt;
    }
    
    struct CylinderType {
        uint256 id;
        uint256 companyId;
        string name;           // "6kg LPG", "12kg LPG", "15kg LPG"
        uint256 capacityKg;    // 6, 12, or 15
        uint256 depositAmount; // Deposit value in wei (optional)
        bool isActive;
    }
    
    // State variables
    uint256 public companyCount;
    uint256 public branchCount;
    uint256 public cylinderTypeCount;
    
    // Mappings
    mapping(uint256 => Company) public companies;
    mapping(uint256 => Branch) public branches;
    mapping(uint256 => CylinderType) public cylinderTypes;
    
    // Company code to ID mapping for quick lookup
    mapping(string => uint256) public companyCodeToId;
    
    // Branch inventory: branchId => cylinderTypeId => count
    mapping(uint256 => mapping(uint256 => uint256)) public branchInventory;
    
    // Company to branches mapping
    mapping(uint256 => uint256[]) public companyBranches;
    
    // Events
    event CompanyRegistered(uint256 indexed companyId, string name, string code);
    event CompanyUpdated(uint256 indexed companyId, bool isActive);
    event BranchRegistered(uint256 indexed branchId, uint256 indexed companyId, string name, string district);
    event BranchUpdated(uint256 indexed branchId, bool isActive);
    event CylinderTypeRegistered(uint256 indexed typeId, uint256 indexed companyId, uint256 capacityKg);
    event InventoryUpdated(uint256 indexed branchId, uint256 indexed cylinderTypeId, uint256 newCount);
    
    // Rwanda districts - 30 districts across all provinces
    string[30] private RWANDA_DISTRICTS = [
        "Bugesera",    // Eastern
        "Burera",      // Northern
        "Gakenke",     // Northern
        "Gasabo",      // Kigali City
        "Gatsibo",     // Eastern
        "Gicumbi",     // Northern
        "Gisagara",    // Southern
        "Huye",        // Southern
        "Kamonyi",     // Southern
        "Karongi",     // Western
        "Kayonza",     // Eastern
        "Kicukiro",    // Kigali City
        "Kirehe",      // Eastern
        "Muhanga",     // Southern
        "Musanze",     // Northern
        "Ngoma",       // Eastern
        "Ngororero",   // Western
        "Nyabihu",     // Western
        "Nyagatare",   // Eastern
        "Nyamagabe",   // Southern
        "Nyamasheke",  // Western
        "Nyanza",      // Southern
        "Nyarugenge",  // Kigali City
        "Nyaruguru",   // Southern
        "Rubavu",      // Western
        "Ruhango",     // Southern
        "Rulindo",     // Northern
        "Rusizi",      // Western
        "Rutsiro",     // Western
        "Rwamagana"    // Eastern
    ];
    
    constructor() {
        // Initialize with default Rwanda gas companies
        _registerDefaultCompanies();
    }
    
    /**
     * @dev Register default gas companies in Rwanda
     * Each company gets branches in all 30 districts = 210 total branches
     */
    function _registerDefaultCompanies() internal {
        _registerCompany("SP Rwanda", "SP", address(0));
        _registerCompany("Oryx Energies", "ORYX", address(0));
        _registerCompany("Tahacel Gas", "TAHACEL", address(0));
        _registerCompany("Kigaligas", "KIGALIGAS", address(0));
        _registerCompany("Hash Gas", "HASH", address(0));
        _registerCompany("Meru Gas", "MERU", address(0));
        _registerCompany("Jibu Gas", "JIBU", address(0));
    }
    
    // Track which companies have had branches initialized
    mapping(uint256 => bool) public companyBranchesInitialized;
    
    /**
     * @dev Internal function to register a company
     */
    function _registerCompany(string memory name, string memory code, address admin) internal {
        companyCount++;
        
        companies[companyCount] = Company({
            id: companyCount,
            name: name,
            code: code,
            isActive: true,
            adminWallet: admin,
            createdAt: block.timestamp
        });
        
        companyCodeToId[code] = companyCount;
        
        // Register default cylinder types for the company
        _registerDefaultCylinderTypes(companyCount);
        
        emit CompanyRegistered(companyCount, name, code);
    }
    
    /**
     * @dev Initialize branches for a company in all 30 districts
     * Called after deployment to avoid gas limits
     * Can be called by platform admin or anyone (one-time initialization)
     */
    function initializeCompanyBranches(uint256 companyId) external {
        require(companyId > 0 && companyId <= companyCount, "Invalid company");
        require(!companyBranchesInitialized[companyId], "Branches already initialized");
        require(companies[companyId].isActive, "Company not active");
        
        string memory companyName = companies[companyId].name;
        
        for (uint256 i = 0; i < 30; i++) {
            branchCount++;
            
            string memory branchName = string(abi.encodePacked(companyName, " - ", RWANDA_DISTRICTS[i], " Branch"));
            
            branches[branchCount] = Branch({
                id: branchCount,
                companyId: companyId,
                name: branchName,
                district: RWANDA_DISTRICTS[i],
                location: string(abi.encodePacked(RWANDA_DISTRICTS[i], " District, Rwanda")),
                isActive: true,
                createdAt: block.timestamp
            });
            
            companyBranches[companyId].push(branchCount);
            
            emit BranchRegistered(branchCount, companyId, branchName, RWANDA_DISTRICTS[i]);
        }
        
        companyBranchesInitialized[companyId] = true;
    }
    
    /**
     * @dev Initialize branches for all companies (convenience function)
     * Calls initializeCompanyBranches for each company
     */
    function initializeAllBranches() external {
        for (uint256 c = 1; c <= companyCount; c++) {
            if (!companyBranchesInitialized[c] && companies[c].isActive) {
                this.initializeCompanyBranches(c);
            }
        }
    }
    
    /**
     * @dev Register default cylinder types (6kg, 12kg, 15kg)
     */
    function _registerDefaultCylinderTypes(uint256 companyId) internal {
        // 6kg cylinder
        cylinderTypeCount++;
        cylinderTypes[cylinderTypeCount] = CylinderType({
            id: cylinderTypeCount,
            companyId: companyId,
            name: "6kg LPG",
            capacityKg: 6,
            depositAmount: 0,
            isActive: true
        });
        emit CylinderTypeRegistered(cylinderTypeCount, companyId, 6);
        
        // 12kg cylinder
        cylinderTypeCount++;
        cylinderTypes[cylinderTypeCount] = CylinderType({
            id: cylinderTypeCount,
            companyId: companyId,
            name: "12kg LPG",
            capacityKg: 12,
            depositAmount: 0,
            isActive: true
        });
        emit CylinderTypeRegistered(cylinderTypeCount, companyId, 12);
        
        // 15kg cylinder
        cylinderTypeCount++;
        cylinderTypes[cylinderTypeCount] = CylinderType({
            id: cylinderTypeCount,
            companyId: companyId,
            name: "15kg LPG",
            capacityKg: 15,
            depositAmount: 0,
            isActive: true
        });
        emit CylinderTypeRegistered(cylinderTypeCount, companyId, 15);
    }
    
    /**
     * @dev Register a new company (Platform Admin only)
     */
    function registerCompany(
        string memory name,
        string memory code,
        address adminWallet
    ) external onlyRole(PLATFORM_ADMIN_ROLE) {
        require(bytes(name).length > 0, "Name required");
        require(bytes(code).length > 0, "Code required");
        require(companyCodeToId[code] == 0, "Company code already exists");
        
        _registerCompany(name, code, adminWallet);
        
        if (adminWallet != address(0)) {
            _grantRole(COMPANY_ADMIN_ROLE, adminWallet);
            staffCompany[adminWallet] = companyCount;
        }
    }
    
    /**
     * @dev Register a new branch
     */
    function registerBranch(
        uint256 companyId,
        string memory name,
        string memory district,
        string memory location
    ) external {
        require(companyId > 0 && companyId <= companyCount, "Invalid company");
        require(companies[companyId].isActive, "Company not active");
        require(bytes(name).length > 0, "Name required");
        require(bytes(district).length > 0, "District required");
        
        // Only platform admin or company admin can register branches
        require(
            hasRole(PLATFORM_ADMIN_ROLE, msg.sender) ||
            (hasRole(COMPANY_ADMIN_ROLE, msg.sender) && staffCompany[msg.sender] == companyId),
            "Not authorized"
        );
        
        branchCount++;
        
        branches[branchCount] = Branch({
            id: branchCount,
            companyId: companyId,
            name: name,
            district: district,
            location: location,
            isActive: true,
            createdAt: block.timestamp
        });
        
        companyBranches[companyId].push(branchCount);
        
        emit BranchRegistered(branchCount, companyId, name, district);
    }
    
    /**
     * @dev Update branch status
     */
    function updateBranchStatus(uint256 branchId, bool isActive) external {
        require(branchId > 0 && branchId <= branchCount, "Invalid branch");
        
        uint256 companyId = branches[branchId].companyId;
        
        require(
            hasRole(PLATFORM_ADMIN_ROLE, msg.sender) ||
            (hasRole(COMPANY_ADMIN_ROLE, msg.sender) && staffCompany[msg.sender] == companyId),
            "Not authorized"
        );
        
        branches[branchId].isActive = isActive;
        
        emit BranchUpdated(branchId, isActive);
    }
    
    /**
     * @dev Update branch inventory (called by VoucherManager)
     */
    function updateInventory(
        uint256 branchId,
        uint256 cylinderTypeId,
        int256 change
    ) external onlyRole(BRANCH_STAFF_ROLE) {
        require(branchId > 0 && branchId <= branchCount, "Invalid branch");
        require(cylinderTypeId > 0 && cylinderTypeId <= cylinderTypeCount, "Invalid cylinder type");
        
        if (change > 0) {
            branchInventory[branchId][cylinderTypeId] += uint256(change);
        } else if (change < 0) {
            uint256 decrease = uint256(-change);
            require(branchInventory[branchId][cylinderTypeId] >= decrease, "Insufficient inventory");
            branchInventory[branchId][cylinderTypeId] -= decrease;
        }
        
        emit InventoryUpdated(branchId, cylinderTypeId, branchInventory[branchId][cylinderTypeId]);
    }
    
    // View functions
    
    function getCompany(uint256 companyId) external view returns (Company memory) {
        return companies[companyId];
    }
    
    function getBranch(uint256 branchId) external view returns (Branch memory) {
        return branches[branchId];
    }
    
    function getCylinderType(uint256 typeId) external view returns (CylinderType memory) {
        return cylinderTypes[typeId];
    }
    
    function getCompanyByCode(string memory code) external view returns (Company memory) {
        uint256 companyId = companyCodeToId[code];
        require(companyId > 0, "Company not found");
        return companies[companyId];
    }
    
    function getCompanyBranches(uint256 companyId) external view returns (uint256[] memory) {
        return companyBranches[companyId];
    }
    
    function getBranchInventory(uint256 branchId, uint256 cylinderTypeId) external view returns (uint256) {
        return branchInventory[branchId][cylinderTypeId];
    }
    
    function isValidBranch(uint256 branchId) public view returns (bool) {
        return branchId > 0 && branchId <= branchCount && branches[branchId].isActive;
    }
    
    function isValidCompany(uint256 companyId) public view returns (bool) {
        return companyId > 0 && companyId <= companyCount && companies[companyId].isActive;
    }
    
    function isValidCylinderType(uint256 typeId) public view returns (bool) {
        return typeId > 0 && typeId <= cylinderTypeCount && cylinderTypes[typeId].isActive;
    }
    
    function getBranchCompany(uint256 branchId) external view returns (uint256) {
        return branches[branchId].companyId;
    }
    
    /**
     * @dev Get all active company IDs
     */
    function getAllActiveCompanies() external view returns (uint256[] memory) {
        uint256 activeCount = 0;
        
        // Count active companies
        for (uint256 i = 1; i <= companyCount; i++) {
            if (companies[i].isActive) {
                activeCount++;
            }
        }
        
        // Build array of active company IDs
        uint256[] memory activeCompanyIds = new uint256[](activeCount);
        uint256 index = 0;
        for (uint256 i = 1; i <= companyCount; i++) {
            if (companies[i].isActive) {
                activeCompanyIds[index] = i;
                index++;
            }
        }
        
        return activeCompanyIds;
    }
    
    /**
     * @dev Get all active branch IDs for a company
     */
    function getAllActiveBranches(uint256 companyId) external view returns (uint256[] memory) {
        uint256[] memory allBranches = companyBranches[companyId];
        uint256 activeCount = 0;
        
        // Count active branches
        for (uint256 i = 0; i < allBranches.length; i++) {
            if (branches[allBranches[i]].isActive) {
                activeCount++;
            }
        }
        
        // Build array of active branch IDs
        uint256[] memory activeBranchIds = new uint256[](activeCount);
        uint256 index = 0;
        for (uint256 i = 0; i < allBranches.length; i++) {
            if (branches[allBranches[i]].isActive) {
                activeBranchIds[index] = allBranches[i];
                index++;
            }
        }
        
        return activeBranchIds;
    }
    
    /**
     * @dev Get cylinder types for a company
     */
    function getCompanyCylinderTypes(uint256 companyId) external view returns (uint256[] memory) {
        uint256 count = 0;
        
        // Count cylinder types for this company
        for (uint256 i = 1; i <= cylinderTypeCount; i++) {
            if (cylinderTypes[i].companyId == companyId && cylinderTypes[i].isActive) {
                count++;
            }
        }
        
        // Build array
        uint256[] memory typeIds = new uint256[](count);
        uint256 index = 0;
        for (uint256 i = 1; i <= cylinderTypeCount; i++) {
            if (cylinderTypes[i].companyId == companyId && cylinderTypes[i].isActive) {
                typeIds[index] = i;
                index++;
            }
        }
        
        return typeIds;
    }
    
    /**
     * @dev Get all district names
     */
    function getAllDistricts() external view returns (string[30] memory) {
        return RWANDA_DISTRICTS;
    }
    
    /**
     * @dev Get branch by company and district index
     * @param companyId The company ID (1-7)
     * @param districtIndex The district index (0-29)
     * @return branchId The branch ID
     */
    function getBranchByCompanyAndDistrict(uint256 companyId, uint256 districtIndex) external view returns (uint256) {
        require(companyId > 0 && companyId <= companyCount, "Invalid company");
        require(districtIndex < 30, "Invalid district index");
        
        // Calculate branch ID: each company has 30 branches
        // Branch ID = (companyId - 1) * 30 + districtIndex + 1
        uint256 branchId = (companyId - 1) * 30 + districtIndex + 1;
        
        require(branchId <= branchCount, "Branch not found");
        return branchId;
    }
    
    /**
     * @dev Get all branches in a specific district (across all companies)
     * @param districtIndex The district index (0-29)
     * @return branchIds Array of branch IDs in that district
     */
    function getBranchesByDistrict(uint256 districtIndex) external view returns (uint256[] memory) {
        require(districtIndex < 30, "Invalid district index");
        
        uint256[] memory branchIds = new uint256[](companyCount);
        
        for (uint256 c = 1; c <= companyCount; c++) {
            // Each company's branch for this district
            branchIds[c - 1] = (c - 1) * 30 + districtIndex + 1;
        }
        
        return branchIds;
    }
    
    /**
     * @dev Get district name by index
     */
    function getDistrictName(uint256 districtIndex) external view returns (string memory) {
        require(districtIndex < 30, "Invalid district index");
        return RWANDA_DISTRICTS[districtIndex];
    }
    
    /**
     * @dev Get total number of branches (should be 210 for 7 companies × 30 districts)
     */
    function getTotalBranchCount() external view returns (uint256) {
        return branchCount;
    }
}

contracts/CylinderRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title CylinderRegistry
 * @dev NFT-based registry for physical gas cylinders
 * 
 * Each physical cylinder is represented as an NFT with metadata
 * tracking its location, status, and history.
 */
contract CylinderRegistry is ERC721, ERC721Enumerable, AccessControl, Pausable {
    
    bytes32 public constant PLATFORM_ADMIN_ROLE = keccak256("PLATFORM_ADMIN_ROLE");
    bytes32 public constant BRANCH_STAFF_ROLE = keccak256("BRANCH_STAFF_ROLE");
    
    // Cylinder status enum
    enum CylinderStatus {
        IN_BRANCH,      // Cylinder is at a branch, available for swap
        IN_TRANSIT,     // Cylinder is being transferred
        WITH_CUSTOMER,  // Cylinder is with a customer (deposited for voucher)
        MAINTENANCE,    // Cylinder is under maintenance/inspection
        RETIRED         // Cylinder is no longer in service
    }
    
    // Cylinder data structure
    struct CylinderData {
        uint256 companyId;
        uint256 cylinderTypeId;    // Reference to cylinder type (6kg, 12kg, 15kg)
        string serialNumber;        // Physical serial number on cylinder
        uint256 currentBranchId;    // Current location (branch ID)
        CylinderStatus status;
        uint256 manufacturingDate;
        uint256 lastInspectionDate;
        uint256 registeredAt;
    }
    
    // Transfer record for history tracking
    struct TransferRecord {
        uint256 fromBranchId;
        uint256 toBranchId;
        address initiatedBy;
        uint256 timestamp;
        string reason;
    }
    
    // State variables
    uint256 private _tokenIdCounter;
    
    // Mappings
    mapping(uint256 => CylinderData) public cylinderData;
    mapping(string => uint256) public serialNumberToTokenId;  // Serial number lookup
    mapping(uint256 => TransferRecord[]) public cylinderHistory;
    
    // Events
    event CylinderRegistered(
        uint256 indexed tokenId,
        uint256 indexed companyId,
        uint256 cylinderTypeId,
        string serialNumber,
        uint256 branchId
    );
    
    event CylinderStatusChanged(
        uint256 indexed tokenId,
        CylinderStatus oldStatus,
        CylinderStatus newStatus,
        uint256 branchId
    );
    
    event CylinderTransferred(
        uint256 indexed tokenId,
        uint256 fromBranchId,
        uint256 toBranchId,
        address initiatedBy
    );
    
    event CylinderInspected(uint256 indexed tokenId, uint256 inspectionDate);
    
    constructor() ERC721("GasCylinder", "GCYL") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PLATFORM_ADMIN_ROLE, msg.sender);
    }
    
    /**
     * @dev Register a new physical cylinder on the blockchain
     * @param companyId Company that owns this cylinder
     * @param cylinderTypeId Type ID (6kg, 12kg, 15kg)
     * @param serialNumber Physical serial number
     * @param branchId Initial branch location
     * @param manufacturingDate Manufacturing date timestamp
     */
    function registerCylinder(
        uint256 companyId,
        uint256 cylinderTypeId,
        string memory serialNumber,
        uint256 branchId,
        uint256 manufacturingDate
    ) external onlyRole(BRANCH_STAFF_ROLE) whenNotPaused returns (uint256) {
        require(companyId > 0, "Invalid company ID");
        require(cylinderTypeId > 0, "Invalid cylinder type");
        require(bytes(serialNumber).length > 0, "Serial number required");
        require(branchId > 0, "Invalid branch ID");
        require(serialNumberToTokenId[serialNumber] == 0, "Serial number already registered");
        
        _tokenIdCounter++;
        uint256 tokenId = _tokenIdCounter;
        
        // Store cylinder data
        cylinderData[tokenId] = CylinderData({
            companyId: companyId,
            cylinderTypeId: cylinderTypeId,
            serialNumber: serialNumber,
            currentBranchId: branchId,
            status: CylinderStatus.IN_BRANCH,
            manufacturingDate: manufacturingDate,
            lastInspectionDate: block.timestamp,
            registeredAt: block.timestamp
        });
        
        // Map serial number to token ID
        serialNumberToTokenId[serialNumber] = tokenId;
        
        // Mint NFT to contract (cylinders are owned by the platform)
        // Using _mint instead of _safeMint since we're minting to this contract
        _mint(address(this), tokenId);
        
        emit CylinderRegistered(tokenId, companyId, cylinderTypeId, serialNumber, branchId);
        
        return tokenId;
    }
    
    /**
     * @dev Update cylinder status (used during deposit/redemption)
     * @param tokenId Cylinder token ID
     * @param newStatus New status
     * @param branchId Branch where status change occurs
     */
    function updateCylinderStatus(
        uint256 tokenId,
        CylinderStatus newStatus,
        uint256 branchId
    ) external onlyRole(BRANCH_STAFF_ROLE) whenNotPaused {
        require(_exists(tokenId), "Cylinder does not exist");
        
        CylinderData storage cylinder = cylinderData[tokenId];
        CylinderStatus oldStatus = cylinder.status;
        uint256 previousBranchId = cylinder.currentBranchId;

        cylinder.status = newStatus;
        cylinder.currentBranchId = branchId;

        // Record in history
        cylinderHistory[tokenId].push(TransferRecord({
            fromBranchId: previousBranchId,
            toBranchId: branchId,
            initiatedBy: msg.sender,
            timestamp: block.timestamp,
            reason: _statusToString(newStatus)
        }));
        
        emit CylinderStatusChanged(tokenId, oldStatus, newStatus, branchId);
    }
    
    /**
     * @dev Transfer cylinder between branches
     * @param tokenId Cylinder token ID
     * @param fromBranchId Source branch
     * @param toBranchId Destination branch
     */
    function transferCylinder(
        uint256 tokenId,
        uint256 fromBranchId,
        uint256 toBranchId
    ) external onlyRole(BRANCH_STAFF_ROLE) whenNotPaused {
        require(_exists(tokenId), "Cylinder does not exist");
        require(fromBranchId != toBranchId, "Same branch transfer");
        
        CylinderData storage cylinder = cylinderData[tokenId];
        require(cylinder.currentBranchId == fromBranchId, "Cylinder not at source branch");
        require(cylinder.status == CylinderStatus.IN_BRANCH, "Cylinder not available");
        
        cylinder.currentBranchId = toBranchId;
        
        // Record transfer in history
        cylinderHistory[tokenId].push(TransferRecord({
            fromBranchId: fromBranchId,
            toBranchId: toBranchId,
            initiatedBy: msg.sender,
            timestamp: block.timestamp,
            reason: "Inter-branch transfer"
        }));
        
        emit CylinderTransferred(tokenId, fromBranchId, toBranchId, msg.sender);
    }
    
    /**
     * @dev Record cylinder inspection
     * @param tokenId Cylinder token ID
     */
    function recordInspection(uint256 tokenId) external onlyRole(BRANCH_STAFF_ROLE) {
        require(_exists(tokenId), "Cylinder does not exist");
        
        cylinderData[tokenId].lastInspectionDate = block.timestamp;
        
        emit CylinderInspected(tokenId, block.timestamp);
    }
    
    /**
     * @dev Retire a cylinder
     * @param tokenId Cylinder token ID
     */
    function retireCylinder(uint256 tokenId) external onlyRole(PLATFORM_ADMIN_ROLE) {
        require(_exists(tokenId), "Cylinder does not exist");
        
        cylinderData[tokenId].status = CylinderStatus.RETIRED;
        
        emit CylinderStatusChanged(
            tokenId, 
            cylinderData[tokenId].status, 
            CylinderStatus.RETIRED, 
            cylinderData[tokenId].currentBranchId
        );
    }
    
    // View functions
    
    function getCylinder(uint256 tokenId) external view returns (CylinderData memory) {
        require(_exists(tokenId), "Cylinder does not exist");
        return cylinderData[tokenId];
    }
    
    function getCylinderBySerial(string memory serialNumber) external view returns (uint256, CylinderData memory) {
        uint256 tokenId = serialNumberToTokenId[serialNumber];
        require(tokenId > 0, "Cylinder not found");
        return (tokenId, cylinderData[tokenId]);
    }
    
    function getCylinderHistory(uint256 tokenId) external view returns (TransferRecord[] memory) {
        return cylinderHistory[tokenId];
    }
    
    function isCylinderAvailable(uint256 tokenId) public view returns (bool) {
        if (!_exists(tokenId)) return false;
        return cylinderData[tokenId].status == CylinderStatus.IN_BRANCH;
    }
    
    function isCylinderAtBranch(uint256 tokenId, uint256 branchId) public view returns (bool) {
        if (!_exists(tokenId)) return false;
        CylinderData memory cylinder = cylinderData[tokenId];
        return cylinder.currentBranchId == branchId && cylinder.status == CylinderStatus.IN_BRANCH;
    }
    
    function getTotalCylinders() external view returns (uint256) {
        return _tokenIdCounter;
    }
    
    /**
     * @dev Get all available cylinders at a specific branch
     * @param branchId Branch to query
     * @return serialNumbers Array of serial numbers of available cylinders
     * @return tokenIds Array of token IDs
     */
    function getAvailableCylindersAtBranch(uint256 branchId) external view returns (
        string[] memory serialNumbers,
        uint256[] memory tokenIds
    ) {
        // First count available cylinders
        uint256 count = 0;
        for (uint256 i = 1; i <= _tokenIdCounter; i++) {
            if (cylinderData[i].currentBranchId == branchId && 
                cylinderData[i].status == CylinderStatus.IN_BRANCH) {
                count++;
            }
        }
        
        // Build arrays
        serialNumbers = new string[](count);
        tokenIds = new uint256[](count);
        uint256 index = 0;
        
        for (uint256 i = 1; i <= _tokenIdCounter; i++) {
            if (cylinderData[i].currentBranchId == branchId && 
                cylinderData[i].status == CylinderStatus.IN_BRANCH) {
                serialNumbers[index] = cylinderData[i].serialNumber;
                tokenIds[index] = i;
                index++;
            }
        }
        
        return (serialNumbers, tokenIds);
    }
    
    function _exists(uint256 tokenId) internal view returns (bool) {
        return tokenId > 0 && tokenId <= _tokenIdCounter;
    }
    
    function _statusToString(CylinderStatus status) internal pure returns (string memory) {
        if (status == CylinderStatus.IN_BRANCH) return "In Branch";
        if (status == CylinderStatus.IN_TRANSIT) return "In Transit";
        if (status == CylinderStatus.WITH_CUSTOMER) return "With Customer";
        if (status == CylinderStatus.MAINTENANCE) return "Maintenance";
        if (status == CylinderStatus.RETIRED) return "Retired";
        return "Unknown";
    }
    
    // Required overrides
    
    function pause() external onlyRole(PLATFORM_ADMIN_ROLE) {
        _pause();
    }
    
    function unpause() external onlyRole(PLATFORM_ADMIN_ROLE) {
        _unpause();
    }
    
    function _update(address to, uint256 tokenId, address auth)
        internal
        override(ERC721, ERC721Enumerable)
        returns (address)
    {
        return super._update(to, tokenId, auth);
    }

    function _increaseBalance(address account, uint128 value)
        internal
        override(ERC721, ERC721Enumerable)
    {
        super._increaseBalance(account, value);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721Enumerable, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/GasSwapAccessControl.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title GasSwapAccessControl
 * @dev Role-based access control for the Gas Cylinder Swap Platform
 * 
 * Roles:
 * - PLATFORM_ADMIN: Can manage companies, pause system
 * - COMPANY_ADMIN: Can manage branches and staff for their company
 * - BRANCH_STAFF: Can create and redeem vouchers
 */
contract GasSwapAccessControl is AccessControl, Pausable {
    
    // Role definitions
    bytes32 public constant PLATFORM_ADMIN_ROLE = keccak256("PLATFORM_ADMIN_ROLE");
    bytes32 public constant COMPANY_ADMIN_ROLE = keccak256("COMPANY_ADMIN_ROLE");
    bytes32 public constant BRANCH_STAFF_ROLE = keccak256("BRANCH_STAFF_ROLE");
    
    // Mapping: staff address => company ID
    mapping(address => uint256) public staffCompany;
    
    // Mapping: staff address => branch ID
    mapping(address => uint256) public staffBranch;
    
    // Events
    event StaffAssigned(address indexed staff, uint256 indexed companyId, uint256 indexed branchId);
    event StaffRemoved(address indexed staff);
    
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PLATFORM_ADMIN_ROLE, msg.sender);
    }
    
    /**
     * @dev Assign a company admin
     * @param admin Address to grant company admin role
     * @param companyId Company ID the admin manages
     */
    function assignCompanyAdmin(address admin, uint256 companyId) 
        external 
        onlyRole(PLATFORM_ADMIN_ROLE) 
    {
        require(admin != address(0), "Invalid address");
        require(companyId > 0, "Invalid company ID");
        
        _grantRole(COMPANY_ADMIN_ROLE, admin);
        staffCompany[admin] = companyId;
        
        emit StaffAssigned(admin, companyId, 0);
    }
    
    /**
     * @dev Assign a branch staff member
     * @param staff Address to grant branch staff role
     * @param companyId Company ID
     * @param branchId Branch ID the staff works at
     */
    function assignBranchStaff(address staff, uint256 companyId, uint256 branchId) 
        external 
    {
        require(staff != address(0), "Invalid address");
        require(companyId > 0, "Invalid company ID");
        require(branchId > 0, "Invalid branch ID");
        
        // Only platform admin or company admin of same company can assign
        require(
            hasRole(PLATFORM_ADMIN_ROLE, msg.sender) ||
            (hasRole(COMPANY_ADMIN_ROLE, msg.sender) && staffCompany[msg.sender] == companyId),
            "Not authorized to assign staff"
        );
        
        _grantRole(BRANCH_STAFF_ROLE, staff);
        staffCompany[staff] = companyId;
        staffBranch[staff] = branchId;
        
        emit StaffAssigned(staff, companyId, branchId);
    }
    
    /**
     * @dev Remove staff member
     * @param staff Address to remove
     */
    function removeStaff(address staff) external {
        uint256 companyId = staffCompany[staff];
        
        require(
            hasRole(PLATFORM_ADMIN_ROLE, msg.sender) ||
            (hasRole(COMPANY_ADMIN_ROLE, msg.sender) && staffCompany[msg.sender] == companyId),
            "Not authorized to remove staff"
        );
        
        _revokeRole(BRANCH_STAFF_ROLE, staff);
        _revokeRole(COMPANY_ADMIN_ROLE, staff);
        
        delete staffCompany[staff];
        delete staffBranch[staff];
        
        emit StaffRemoved(staff);
    }
    
    /**
     * @dev Pause the system (emergency stop)
     */
    function pause() external onlyRole(PLATFORM_ADMIN_ROLE) {
        _pause();
    }
    
    /**
     * @dev Unpause the system
     */
    function unpause() external onlyRole(PLATFORM_ADMIN_ROLE) {
        _unpause();
    }
    
    /**
     * @dev Check if address is staff of a specific company
     */
    function isCompanyStaff(address staff, uint256 companyId) public view returns (bool) {
        return staffCompany[staff] == companyId && 
               (hasRole(BRANCH_STAFF_ROLE, staff) || hasRole(COMPANY_ADMIN_ROLE, staff));
    }
    
    /**
     * @dev Check if address is staff of a specific branch
     */
    function isBranchStaff(address staff, uint256 branchId) public view returns (bool) {
        return staffBranch[staff] == branchId && hasRole(BRANCH_STAFF_ROLE, staff);
    }
    
    /**
     * @dev Get staff's company ID
     */
    function getStaffCompany(address staff) external view returns (uint256) {
        return staffCompany[staff];
    }
    
    /**
     * @dev Get staff's branch ID
     */
    function getStaffBranch(address staff) external view returns (uint256) {
        return staffBranch[staff];
    }
}

contracts/GasSwapPlatform.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./CompanyManager.sol";
import "./CylinderRegistry.sol";
import "./VoucherManager.sol";

/**
 * @title GasSwapPlatform
 * @dev Main orchestrating contract for the Gas Cylinder Swap Platform
 * 
 * This contract coordinates between CompanyManager, CylinderRegistry,
 * and VoucherManager to provide a unified interface for the platform.
 */
contract GasSwapPlatform is GasSwapAccessControl {
    
    // Contract references
    CompanyManager public companyManager;
    CylinderRegistry public cylinderRegistry;
    VoucherManager public voucherManager;
    
    // Platform statistics
    uint256 public totalSwapsCompleted;
    uint256 public platformLaunchDate;
    
    // Events
    event PlatformInitialized(
        address companyManager,
        address cylinderRegistry,
        address voucherManager
    );
    
    event SwapInitiated(
        uint256 indexed voucherId,
        address indexed customer,
        uint256 companyId,
        uint256 cylinderTypeId,
        uint256 sourceBranchId
    );
    
    event SwapCompleted(
        uint256 indexed voucherId,
        address indexed customer,
        uint256 sourceBranchId,
        uint256 redemptionBranchId
    );
    
    constructor(
        address _companyManager,
        address _cylinderRegistry,
        address _voucherManager
    ) {
        require(_companyManager != address(0), "Invalid CompanyManager");
        require(_cylinderRegistry != address(0), "Invalid CylinderRegistry");
        require(_voucherManager != address(0), "Invalid VoucherManager");
        
        companyManager = CompanyManager(_companyManager);
        cylinderRegistry = CylinderRegistry(_cylinderRegistry);
        voucherManager = VoucherManager(_voucherManager);
        
        platformLaunchDate = block.timestamp;
        
        emit PlatformInitialized(_companyManager, _cylinderRegistry, _voucherManager);
    }
    
    /**
     * @dev Initiate a cylinder swap (deposit cylinder, get voucher)
     * @param customer Customer wallet address
     * @param cylinderSerialNumber Serial number of cylinder being deposited
     * @param branchId Branch where deposit occurs
     * @param customerName Customer full name
     * @param customerEmail Customer email address
     * @param customerPhone Customer phone number
     * @return voucherId The created voucher ID
     */
    function initiateSwap(
        address customer,
        string memory cylinderSerialNumber,
        uint256 branchId,
        string memory customerName,
        string memory customerEmail,
        string memory customerPhone
    ) external onlyRole(BRANCH_STAFF_ROLE) whenNotPaused returns (uint256) {
        // Get cylinder by serial number
        (uint256 cylinderId, CylinderRegistry.CylinderData memory cylinder) = 
            cylinderRegistry.getCylinderBySerial(cylinderSerialNumber);
        
        require(cylinderId > 0, "Cylinder not registered");
        require(cylinder.status != CylinderRegistry.CylinderStatus.RETIRED, "Cylinder is retired");
        
        // Validate branch
        require(companyManager.isValidBranch(branchId), "Invalid branch");
        CompanyManager.Branch memory branch = companyManager.getBranch(branchId);
        require(branch.companyId == cylinder.companyId, "Company mismatch");
        
        // Update cylinder status to "with customer"
        cylinderRegistry.updateCylinderStatus(
            cylinderId,
            CylinderRegistry.CylinderStatus.WITH_CUSTOMER,
            branchId
        );
        
        // Create voucher
        uint256 voucherId = voucherManager.createVoucher(
            customer,
            cylinder.companyId,
            cylinder.cylinderTypeId,
            branchId,
            cylinderId,
            customerName,
            customerEmail,
            customerPhone
        );
        
        emit SwapInitiated(
            voucherId,
            customer,
            cylinder.companyId,
            cylinder.cylinderTypeId,
            branchId
        );
        
        return voucherId;
    }
    
    /**
     * @dev Complete a swap (redeem voucher, get new cylinder)
     * @param voucherId Voucher to redeem
     * @param newCylinderSerialNumber Serial number of cylinder to give customer
     * @param branchId Branch where redemption occurs
     */
    function completeSwap(
        uint256 voucherId,
        string memory newCylinderSerialNumber,
        uint256 branchId
    ) external onlyRole(BRANCH_STAFF_ROLE) whenNotPaused {
        // Validate voucher
        require(voucherManager.isVoucherValid(voucherId), "Invalid or expired voucher");
        
        VoucherManager.Voucher memory voucher = voucherManager.getVoucher(voucherId);
        
        // Validate branch
        require(companyManager.isValidBranch(branchId), "Invalid branch");
        CompanyManager.Branch memory redemptionBranch = companyManager.getBranch(branchId);
        require(redemptionBranch.companyId == voucher.companyId, "Must redeem at same company");
        
        // Get new cylinder
        (uint256 newCylinderId, CylinderRegistry.CylinderData memory newCylinder) = 
            cylinderRegistry.getCylinderBySerial(newCylinderSerialNumber);
        
        require(newCylinderId > 0, "New cylinder not registered");
        require(cylinderRegistry.isCylinderAtBranch(newCylinderId, branchId), "Cylinder not at this branch");
        require(newCylinder.companyId == voucher.companyId, "Company mismatch");
        require(newCylinder.cylinderTypeId == voucher.cylinderTypeId, "Cylinder type mismatch");
        
        // Update new cylinder status
        cylinderRegistry.updateCylinderStatus(
            newCylinderId,
            CylinderRegistry.CylinderStatus.WITH_CUSTOMER,
            branchId
        );
        
        // Redeem voucher
        voucherManager.redeemVoucher(voucherId, branchId, newCylinderId);
        
        totalSwapsCompleted++;
        
        emit SwapCompleted(
            voucherId,
            voucher.customer,
            voucher.sourceBranchId,
            branchId
        );
    }
    
    /**
     * @dev Verify a voucher (public function for QR code verification)
     * @param voucherId Voucher to verify
     * @return isValid Whether voucher is valid
     * @return companyId Company ID
     * @return cylinderTypeId Cylinder type
     * @return daysRemaining Days until expiration
     * @return status Status string
     */
    function verifyVoucher(uint256 voucherId) external view returns (
        bool isValid,
        uint256 companyId,
        uint256 cylinderTypeId,
        uint256 daysRemaining,
        string memory status
    ) {
        isValid = voucherManager.isVoucherValid(voucherId);
        
        if (voucherId > 0 && voucherId <= voucherManager.getTotalVouchers()) {
            VoucherManager.Voucher memory voucher = voucherManager.getVoucher(voucherId);
            companyId = voucher.companyId;
            cylinderTypeId = voucher.cylinderTypeId;
            daysRemaining = voucherManager.getDaysRemaining(voucherId);
            status = voucherManager.getVoucherStatusString(voucherId);
        }
        
        return (isValid, companyId, cylinderTypeId, daysRemaining, status);
    }
    
    /**
     * @dev Get platform statistics
     */
    function getPlatformStats() external view returns (
        uint256 totalCompanies,
        uint256 totalBranches,
        uint256 totalCylinders,
        uint256 totalVouchers,
        uint256 completedSwaps,
        uint256 launchDate
    ) {
        return (
            companyManager.companyCount(),
            companyManager.branchCount(),
            cylinderRegistry.getTotalCylinders(),
            voucherManager.getTotalVouchers(),
            totalSwapsCompleted,
            platformLaunchDate
        );
    }
    
    /**
     * @dev Get company info with branch count
     */
    function getCompanyInfo(uint256 companyId) external view returns (
        string memory name,
        string memory code,
        bool isActive,
        uint256 branchCount,
        uint256 totalDeposits,
        uint256 totalRedemptions,
        int256 netBalance
    ) {
        CompanyManager.Company memory company = companyManager.getCompany(companyId);
        uint256[] memory branches = companyManager.getCompanyBranches(companyId);
        
        (uint256 deposits, uint256 redemptions, int256 balance) = 
            voucherManager.getCompanyBalance(companyId);
        
        return (
            company.name,
            company.code,
            company.isActive,
            branches.length,
            deposits,
            redemptions,
            balance
        );
    }
    
    /**
     * @dev Check if a cylinder type is available at a branch
     */
    function checkAvailability(
        uint256 branchId,
        uint256 cylinderTypeId
    ) external view returns (uint256 available) {
        return companyManager.getBranchInventory(branchId, cylinderTypeId);
    }
    
    /**
     * @dev Get customer's active vouchers
     */
    function getCustomerActiveVouchers(address customer) external view returns (
        uint256[] memory activeVoucherIds
    ) {
        uint256[] memory allVouchers = voucherManager.getCustomerVouchers(customer);
        
        // Count active vouchers
        uint256 activeCount = 0;
        for (uint256 i = 0; i < allVouchers.length; i++) {
            if (voucherManager.isVoucherValid(allVouchers[i])) {
                activeCount++;
            }
        }
        
        // Build array of active voucher IDs
        activeVoucherIds = new uint256[](activeCount);
        uint256 index = 0;
        for (uint256 i = 0; i < allVouchers.length; i++) {
            if (voucherManager.isVoucherValid(allVouchers[i])) {
                activeVoucherIds[index] = allVouchers[i];
                index++;
            }
        }
        
        return activeVoucherIds;
    }
    
    /**
     * @dev Update contract references (admin only)
     */
    function updateContracts(
        address _companyManager,
        address _cylinderRegistry,
        address _voucherManager
    ) external onlyRole(PLATFORM_ADMIN_ROLE) {
        if (_companyManager != address(0)) {
            companyManager = CompanyManager(_companyManager);
        }
        if (_cylinderRegistry != address(0)) {
            cylinderRegistry = CylinderRegistry(_cylinderRegistry);
        }
        if (_voucherManager != address(0)) {
            voucherManager = VoucherManager(_voucherManager);
        }
        
        emit PlatformInitialized(
            address(companyManager),
            address(cylinderRegistry),
            address(voucherManager)
        );
    }
}

contracts/VoucherManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title VoucherManager
 * @dev Core contract for managing gas cylinder swap vouchers
 * 
 * A voucher is created when a customer deposits a cylinder and can be
 * redeemed at any branch of the same company for an equivalent cylinder.
 */
contract VoucherManager is ERC721, ERC721Enumerable, AccessControl, Pausable, ReentrancyGuard {
    
    bytes32 public constant PLATFORM_ADMIN_ROLE = keccak256("PLATFORM_ADMIN_ROLE");
    bytes32 public constant BRANCH_STAFF_ROLE = keccak256("BRANCH_STAFF_ROLE");
    
    // Voucher status enum
    enum VoucherStatus {
        ACTIVE,     // Voucher is valid and can be redeemed
        REDEEMED,   // Voucher has been used
        EXPIRED,    // Voucher has expired (past validity period)
        CANCELLED   // Voucher was cancelled (refund scenario)
    }
    
    // Voucher data structure
    struct Voucher {
        uint256 id;
        uint256 depositedCylinderId;  // Token ID of deposited cylinder
        uint256 companyId;
        uint256 cylinderTypeId;       // Type of cylinder (6kg, 12kg, 15kg)
        uint256 sourceBranchId;       // Where cylinder was deposited
        address customer;              // Customer wallet address
        uint256 createdAt;
        uint256 expiresAt;
        VoucherStatus status;
        // Redemption details (filled when redeemed)
        uint256 redeemedCylinderId;
        uint256 redemptionBranchId;
        uint256 redeemedAt;
        address redeemedBy;           // Staff who processed redemption
    }
    
    // Customer information structure
    struct CustomerInfo {
        string name;
        string email;
        string phoneNumber;
    }
    
    // Company balance tracking
    struct CompanyBalance {
        uint256 totalDeposits;
        uint256 totalRedemptions;
        int256 netBalance;  // Deposits - Redemptions
    }
    
    // Constants
    uint256 public constant VOUCHER_VALIDITY_DAYS = 30;
    
    // State variables
    uint256 private _voucherIdCounter;
    
    // Mappings
    mapping(uint256 => Voucher) public vouchers;
    mapping(uint256 => CustomerInfo) public voucherCustomerInfo;
    mapping(uint256 => CompanyBalance) public companyBalances;
    mapping(address => uint256[]) public customerVouchers;  // Customer's voucher history
    
    // Branch statistics
    mapping(uint256 => uint256) public branchDeposits;
    mapping(uint256 => uint256) public branchRedemptions;
    
    // Events
    event VoucherCreated(
        uint256 indexed voucherId,
        address indexed customer,
        uint256 indexed companyId,
        uint256 cylinderTypeId,
        uint256 sourceBranchId,
        uint256 depositedCylinderId,
        uint256 expiresAt,
        string customerName
    );
    
    event VoucherRedeemed(
        uint256 indexed voucherId,
        address indexed customer,
        uint256 indexed redemptionBranchId,
        uint256 redeemedCylinderId,
        address redeemedBy
    );
    
    event VoucherCancelled(
        uint256 indexed voucherId,
        address indexed customer,
        string reason
    );
    
    event VoucherExpired(uint256 indexed voucherId);
    
    constructor() ERC721("GasSwapVoucher", "GSV") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PLATFORM_ADMIN_ROLE, msg.sender);
    }
    
    /**
     * @dev Create a new voucher when customer deposits a cylinder
     * @param customer Customer's wallet address
     * @param companyId Company ID
     * @param cylinderTypeId Cylinder type (6kg, 12kg, 15kg)
     * @param sourceBranchId Branch where deposit occurs
     * @param depositedCylinderId Token ID of the deposited cylinder
     * @param customerName Customer full name
     * @param customerEmail Customer email address
     * @param customerPhone Customer phone number
     * @return voucherId The ID of the created voucher
     */
    function createVoucher(
        address customer,
        uint256 companyId,
        uint256 cylinderTypeId,
        uint256 sourceBranchId,
        uint256 depositedCylinderId,
        string memory customerName,
        string memory customerEmail,
        string memory customerPhone
    ) external onlyRole(BRANCH_STAFF_ROLE) whenNotPaused nonReentrant returns (uint256) {
        require(customer != address(0), "Invalid customer address");
        require(companyId > 0, "Invalid company ID");
        require(cylinderTypeId > 0, "Invalid cylinder type");
        require(sourceBranchId > 0, "Invalid branch ID");
        require(depositedCylinderId > 0, "Invalid cylinder ID");
        
        _voucherIdCounter++;
        uint256 voucherId = _voucherIdCounter;
        
        uint256 expiresAt = block.timestamp + (VOUCHER_VALIDITY_DAYS * 1 days);
        
        // Create voucher record
        vouchers[voucherId] = Voucher({
            id: voucherId,
            depositedCylinderId: depositedCylinderId,
            companyId: companyId,
            cylinderTypeId: cylinderTypeId,
            sourceBranchId: sourceBranchId,
            customer: customer,
            createdAt: block.timestamp,
            expiresAt: expiresAt,
            status: VoucherStatus.ACTIVE,
            redeemedCylinderId: 0,
            redemptionBranchId: 0,
            redeemedAt: 0,
            redeemedBy: address(0)
        });
        
        // Store customer info
        voucherCustomerInfo[voucherId] = CustomerInfo({
            name: customerName,
            email: customerEmail,
            phoneNumber: customerPhone
        });
        
        // Update statistics
        companyBalances[companyId].totalDeposits++;
        companyBalances[companyId].netBalance++;
        branchDeposits[sourceBranchId]++;
        
        // Track customer's vouchers
        customerVouchers[customer].push(voucherId);
        
        // Mint voucher NFT to customer
        _safeMint(customer, voucherId);
        
        emit VoucherCreated(
            voucherId,
            customer,
            companyId,
            cylinderTypeId,
            sourceBranchId,
            depositedCylinderId,
            expiresAt,
            customerName
        );
        
        return voucherId;
    }
    
    /**
     * @dev Redeem a voucher at a destination branch
     * @param voucherId Voucher to redeem
     * @param redemptionBranchId Branch where redemption occurs
     * @param redeemedCylinderId Token ID of cylinder given to customer
     */
    function redeemVoucher(
        uint256 voucherId,
        uint256 redemptionBranchId,
        uint256 redeemedCylinderId
    ) external onlyRole(BRANCH_STAFF_ROLE) whenNotPaused nonReentrant {
        require(voucherId > 0 && voucherId <= _voucherIdCounter, "Invalid voucher ID");
        
        Voucher storage voucher = vouchers[voucherId];
        
        // Validate voucher
        require(voucher.status == VoucherStatus.ACTIVE, "Voucher not active");
        require(block.timestamp <= voucher.expiresAt, "Voucher expired");
        require(redemptionBranchId > 0, "Invalid branch ID");
        require(redeemedCylinderId > 0, "Invalid cylinder ID");
        
        // Update voucher status
        voucher.status = VoucherStatus.REDEEMED;
        voucher.redeemedCylinderId = redeemedCylinderId;
        voucher.redemptionBranchId = redemptionBranchId;
        voucher.redeemedAt = block.timestamp;
        voucher.redeemedBy = msg.sender;
        
        // Update statistics
        companyBalances[voucher.companyId].totalRedemptions++;
        companyBalances[voucher.companyId].netBalance--;
        branchRedemptions[redemptionBranchId]++;
        
        // Burn the voucher NFT
        _burn(voucherId);
        
        emit VoucherRedeemed(
            voucherId,
            voucher.customer,
            redemptionBranchId,
            redeemedCylinderId,
            msg.sender
        );
    }
    
    /**
     * @dev Cancel a voucher (admin function for refund scenarios)
     * @param voucherId Voucher to cancel
     * @param reason Reason for cancellation
     */
    function cancelVoucher(
        uint256 voucherId,
        string memory reason
    ) external onlyRole(PLATFORM_ADMIN_ROLE) {
        require(voucherId > 0 && voucherId <= _voucherIdCounter, "Invalid voucher ID");
        
        Voucher storage voucher = vouchers[voucherId];
        require(voucher.status == VoucherStatus.ACTIVE, "Voucher not active");
        
        voucher.status = VoucherStatus.CANCELLED;
        
        // Adjust company balance
        companyBalances[voucher.companyId].totalDeposits--;
        companyBalances[voucher.companyId].netBalance--;
        
        // Burn the voucher NFT
        _burn(voucherId);
        
        emit VoucherCancelled(voucherId, voucher.customer, reason);
    }
    
    /**
     * @dev Mark expired vouchers (can be called by anyone)
     * @param voucherId Voucher to check and mark as expired
     */
    function markExpired(uint256 voucherId) external {
        require(voucherId > 0 && voucherId <= _voucherIdCounter, "Invalid voucher ID");
        
        Voucher storage voucher = vouchers[voucherId];
        require(voucher.status == VoucherStatus.ACTIVE, "Voucher not active");
        require(block.timestamp > voucher.expiresAt, "Voucher not expired yet");
        
        voucher.status = VoucherStatus.EXPIRED;
        
        // Burn the voucher NFT if still exists
        if (_ownerOf(voucherId) != address(0)) {
            _burn(voucherId);
        }
        
        emit VoucherExpired(voucherId);
    }
    
    // View functions
    
    /**
     * @dev Get voucher details
     */
    function getVoucher(uint256 voucherId) external view returns (Voucher memory) {
        require(voucherId > 0 && voucherId <= _voucherIdCounter, "Invalid voucher ID");
        return vouchers[voucherId];
    }
    
    /**
     * @dev Get voucher customer info
     */
    function getVoucherCustomerInfo(uint256 voucherId) external view returns (CustomerInfo memory) {
        require(voucherId > 0 && voucherId <= _voucherIdCounter, "Invalid voucher ID");
        return voucherCustomerInfo[voucherId];
    }
    
    /**
     * @dev Check if voucher is valid for redemption
     */
    function isVoucherValid(uint256 voucherId) public view returns (bool) {
        if (voucherId == 0 || voucherId > _voucherIdCounter) return false;
        
        Voucher memory voucher = vouchers[voucherId];
        return voucher.status == VoucherStatus.ACTIVE && 
               block.timestamp <= voucher.expiresAt;
    }
    
    /**
     * @dev Get customer's voucher IDs
     */
    function getCustomerVouchers(address customer) external view returns (uint256[] memory) {
        return customerVouchers[customer];
    }
    
    /**
     * @dev Get company balance
     */
    function getCompanyBalance(uint256 companyId) external view returns (
        uint256 totalDeposits,
        uint256 totalRedemptions,
        int256 netBalance
    ) {
        CompanyBalance memory balance = companyBalances[companyId];
        return (balance.totalDeposits, balance.totalRedemptions, balance.netBalance);
    }
    
    /**
     * @dev Get total vouchers created
     */
    function getTotalVouchers() external view returns (uint256) {
        return _voucherIdCounter;
    }
    
    /**
     * @dev Get branch statistics
     */
    function getBranchStats(uint256 branchId) external view returns (
        uint256 deposits,
        uint256 redemptions
    ) {
        return (branchDeposits[branchId], branchRedemptions[branchId]);
    }
    
    /**
     * @dev Get voucher status as string
     */
    function getVoucherStatusString(uint256 voucherId) external view returns (string memory) {
        require(voucherId > 0 && voucherId <= _voucherIdCounter, "Invalid voucher ID");
        
        VoucherStatus status = vouchers[voucherId].status;
        
        if (status == VoucherStatus.ACTIVE) return "Active";
        if (status == VoucherStatus.REDEEMED) return "Redeemed";
        if (status == VoucherStatus.EXPIRED) return "Expired";
        if (status == VoucherStatus.CANCELLED) return "Cancelled";
        return "Unknown";
    }
    
    /**
     * @dev Calculate days remaining for voucher
     */
    function getDaysRemaining(uint256 voucherId) external view returns (uint256) {
        require(voucherId > 0 && voucherId <= _voucherIdCounter, "Invalid voucher ID");
        
        Voucher memory voucher = vouchers[voucherId];
        
        if (voucher.status != VoucherStatus.ACTIVE) return 0;
        if (block.timestamp >= voucher.expiresAt) return 0;
        
        return (voucher.expiresAt - block.timestamp) / 1 days;
    }
    
    // Admin functions
    
    function pause() external onlyRole(PLATFORM_ADMIN_ROLE) {
        _pause();
    }
    
    function unpause() external onlyRole(PLATFORM_ADMIN_ROLE) {
        _unpause();
    }
    
    function grantStaffRole(address account) external onlyRole(PLATFORM_ADMIN_ROLE) {
        _grantRole(BRANCH_STAFF_ROLE, account);
    }
    
    function revokeStaffRole(address account) external onlyRole(PLATFORM_ADMIN_ROLE) {
        _revokeRole(BRANCH_STAFF_ROLE, account);
    }
    
    // Required overrides
    
    function _update(address to, uint256 tokenId, address auth)
        internal
        override(ERC721, ERC721Enumerable)
        returns (address)
    {
        return super._update(to, tokenId, auth);
    }

    function _increaseBalance(address account, uint128 value)
        internal
        override(ERC721, ERC721Enumerable)
    {
        super._increaseBalance(account, value);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721Enumerable, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

